<?php
namespace App\Actions\Grading;
use App\Models\{Student,Semester,AcademicTranscript,StudentGrade}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class CalculateTranscriptAction { public function execute(Student $student,?Semester $semester=null,string $type='khs'): AcademicTranscript { $grades=StudentGrade::where('student_id',$student->id)->where('grade_status','published')->with('courseClass.course','courseClass.semester')->when($semester,fn($q)=>$q->whereHas('courseClass',fn($x)=>$x->where('semester_id',$semester->id)))->get(); if($grades->isEmpty()) throw ValidationException::withMessages(['grades'=>'Belum ada nilai published.']); return DB::transaction(function()use($student,$semester,$type,$grades){$credits=0;$quality=0;$items=[];foreach($grades as $g){$course=$g->courseClass?->course;$sks=(int)($course?->credits??0);$gp=(float)($g->grade_point??$this->point($g->letter_grade));$quality+=$gp*$sks;$credits+=$sks;$items[]=['tenant_id'=>$student->tenant_id,'student_grade_id'=>$g->id,'course_id'=>$course->id,'course_code'=>$course->code,'course_name'=>$course->name,'credits'=>$sks,'score'=>$g->final_score,'letter_grade'=>$g->letter_grade,'grade_point'=>$gp,'quality_points'=>$gp*$sks];}$transcript=AcademicTranscript::updateOrCreate(['tenant_id'=>$student->tenant_id,'student_id'=>$student->id,'type'=>$type,'semester_id'=>$semester?->id],['total_credits'=>$credits,'total_quality_points'=>$quality,'gpa'=>$credits?round($quality/$credits,2):0,'status'=>'generated','generated_at'=>now()]);$transcript->items()->delete();$transcript->items()->createMany($items);return $transcript->load('items');}); } private function point(?string $letter):float{return ['A'=>4,'AB'=>3.5,'B'=>3,'BC'=>2.5,'C'=>2,'D'=>1,'E'=>0][$letter]??0;} }
